25	 * `itemKey` doc comment). Prefixed with `kind` because a mixed round draws
26	 * from several pools at once, and a symbol character can coincide with a
27	 * vocab word's exact Thai spelling (e.g. "ณ" is both a consonant and a
28	 * one-character preposition) — without the prefix, rating that symbol and
29	 * that word as two separate items in the same round would silently
30	 * collapse into one record in `recordRating`'s de-dupe below,
31	 * undercounting the round.
32	 *
33	 * Exhaustive on `kind`: a new `GameItem` member must be a compile error
34	 * here rather than silently inheriting another kind's identity rule.
35	 */
36	function itemKeyOf(item: GameItem): string {
37		switch (item.kind) {
38			case "symbol":
39				return `symbol:${item.symbolCharacter}`;
40			case "word":
41				return `word:${item.thaiWord}`;
42			case "sentence":
43				return `sentence:${item.sentenceId}`;
44			default: {
45				const _never: never = item;
46				throw new Error(`unhandled game item: ${JSON.stringify(_never)}`);
47			}
48		}
49	}
50	
51	/**
52	 * A round's ratings, as recorded so far. Every function here is a pure
53	 * function of the arguments it is given — no round-in-progress state ever
54	 * lives on this class, matching `ConductReviewUseCase`/`ReviewService`'s own
55	 * caller-holds-the-session convention (see CONTEXT.md). `AppContext.tsx`
56	 * wires this up as one long-lived singleton; a singleton holding mutable
57	 * per-round state would leak ratings between rounds and between mounts.
58	 *
59	 * No `CardRepository` is ever received here — only `GameItemSelectionService`
60	 * (which wraps it) and `GameHistoryRepository`. There is therefore no code
61	 * path through this use case that could ever call `CardRepository.save` or
62	 * `ReviewableCard.recordReview`: the SRS-isolation guarantee is structural,
63	 * not merely a rule nobody happens to break.
64	 */
65	export class PlayGameUseCase {
66		/**
67		 * Tracks which `GameRoundSummary` objects have already been persisted, so
68		 * that finishing/saving the same completed round twice (a duplicate
69		 * effect run, a duplicate button press) does not append a duplicate
70		 * history entry. Keyed by object identity, not content: two genuinely
71		 * distinct rounds that happen to produce an identical summary are still
72		 * two history entries. A `WeakSet` holds no strong reference, so it
73		 * never keeps a finished round's data alive past the caller's own use of
74		 * it — this is bookkeeping for `saveHistory`'s own idempotency, not
75		 * round-in-progress state.
76		 */
77		private readonly savedSummaries = new WeakSet<GameRoundSummary>();
