90		 * overwriting any prior rating for that same index rather than appending
91		 * a second record for it — recording twice for one item (a stray global
92		 * keypress landing on top of a click, see CONTEXT.md) must not double-
93		 * count that item in the finished summary.
94		 */
95		recordRating(
96			items: readonly GameItem[],
97			ratings: readonly GameRatingRecord[],
98			itemIndex: number,
99			rating: RecallRating,
100		): GameRatingRecord[] {
101			const item = items[itemIndex];
102			if (!item) return [...ratings];
103	
104			const itemKey = itemKeyOf(item);
105			const record: GameRatingRecord = {
106				itemKey,
107				kind: item.kind,
108				challengeDirection: item.challengeDirection,
109				rating,
110			};
111	
112			return [...ratings.filter((r) => r.itemKey !== itemKey), record];
113		}
114	
115		/**
116		 * `accuracy` counts only ratings 4 (Good) and 5 (Easy) as correct — a
117		 * deliberately different, stricter threshold from
118		 * `ReviewService.endReviewSession`'s `rating >= 3`, and rounded half-up.
119		 * `null` if and only if no rating was recorded, distinct from a rated
120		 * round where none of the ratings were Good/Easy (`accuracy: 0`).
121		 */
122		finishRound(ratings: readonly GameRatingRecord[]): GameRoundSummary {
123			const ratingCounts = ALL_RATINGS.reduce(
124				(counts, value) => {
125					counts[value] = ratings.filter((r) => r.rating === value).length;
126					return counts;
127				},
128				{} as Record<RecallRating, number>,
129			);
130	
131			const ratedCount = ratings.length;
132			const correctCount = ratings.filter((r) =>
133				CORRECT_RATINGS.has(r.rating),
134			).length;
135			const accuracy =
136				ratedCount === 0 ? null : Math.round((correctCount / ratedCount) * 100);
137	
138			return { ratingCounts, ratedCount, accuracy };
139		}
140	
141		saveHistory(
142			config: Pick<GameRoundConfig, "pools" | "itemCount">,
143			summary: GameRoundSummary,
144		): void {
145			if (this.savedSummaries.has(summary)) return;
146			this.savedSummaries.add(summary);
147	
148			const entry: GameHistoryEntry = {
149				id: crypto.randomUUID(),
150				playedAt: new Date().toISOString(),
151				pools: config.pools,
152				itemCount: config.itemCount,
153				summary,
154			};
155			this.historyRepository.save(entry);
156		}
