121	function itemKeyOfCard(card: ReviewableCard): string | null {
122		if (card instanceof ScriptPropertyCard) {
123			return `symbol:${card.symbolCharacter}`;
124		}
125		if (card instanceof VocabCard) {
126			const [prefix, thai] = card.id.split(":");
127			if (prefix !== "vocab" || !thai) return null;
128			return `word:${thai}`;
