133		// An `instanceof` chain cannot be made exhaustive by the compiler the way
134		// the `kind` switches below are — `ReviewableCard` is an open hierarchy.
135		// A card class this service does not recognise scores no weight rather
136		// than throwing; `weightOfFor`'s neutral fallback then applies.
137		return null;
138	}
139	
140	function itemKeyOfContent(content: GameItemContent): string {
141		switch (content.kind) {
142			case "symbol":
143				return `symbol:${content.symbolCharacter}`;
144			case "word":
145				return `word:${content.thaiWord}`;
146			case "sentence":
147				return `sentence:${content.sentenceId}`;
148			default: {
149				const _never: never = content;
150				throw new Error(`unhandled game item content: ${JSON.stringify(_never)}`);
151			}
152		}
153	}
