162	 * `GameItemContent` member must be a compile error here, at the one place
163	 * that decides directions, not a silent fallthrough into some other kind's
164	 * rule.
165	 */
166	function assignDirection(
167		content: GameItemContent,
168		rng: RandomSource,
169	): GameItem {
170		switch (content.kind) {
171			case "symbol": {
172				const challengeDirection: SymbolChallengeDirection = !content.audioUrl
173					? "reading"
174					: rng() < 0.5
175						? "dictation"
176						: "reading";
177				return { ...content, challengeDirection };
178			}
179			case "word": {
180				const challengeDirection: WordChallengeDirection = !content.audioUrl
181					? "production"
182					: rng() < 0.5
183						? "dictationTranslate"
184						: "production";
185				return { ...content, challengeDirection };
186			}
187			case "sentence": {
188				const challengeDirection: SentenceChallengeDirection = !content.audioUrl
189					? "reading"
190					: rng() < 0.5
191						? "listening"
192						: "reading";
193				return { ...content, challengeDirection };
194			}
195			default: {
196				const _never: never = content;
197				throw new Error(`unhandled game item content: ${JSON.stringify(_never)}`);
198			}
199		}
200	}
