			scriptCard(symbol.character, `card-${index}`),
		);
		const { useCase: useCase2 } = setUp(cards);
		const items = useCase2.startRound(
			{ ...CONFIG, itemCount: 2 },
			scripted([0.1, 0.6]),
		);
		const ratings = rateAll(useCase2, items, [1, 2]);
		const zeroPercentSummary = useCase2.finishRound(ratings);

